import{_ as t,o,c as s,a5 as r}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"useStorage","description":"useStorage 类别 : State 导出大小 : 1.78 kB 最后更改 : 5天前 相关 : useColorMode, useDark, useLocalStorage, useSessionStorage, useStorageAsync 创建一个可以用来访问和修。","frontmatter":{"title":"useStorage","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"useStorage 类别 : State 导出大小 : 1.78 kB 最后更改 : 5天前 相关 : useColorMode, useDark, useLocalStorage, useSessionStorage, useStorageAsync 创建一个可以用来访问和修。","sidebarWeight":7,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vue-use/useStorage.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/useStorage.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/useStorage.md"}'),a={name:"posts/Vue系统教程/03-响应式与组合式 API/useStorage.md"};function g(l,e,n,u,i,S){return o(),s("div",null,[...e[0]||(e[0]=[r('<div><h1 id="usestorage" tabindex="-1">useStorage <a class="header-anchor" href="#usestorage" aria-label="Permalink to &quot;useStorage&quot;">​</a></h1><blockquote><p>本节目标：理解“useStorage”的核心思路，并能把它用于实际开发或面试表达。 <strong>useStorage</strong><strong>类别</strong>: State <strong>导出大小</strong>: 1.78 kB <strong>最后更改</strong>: 5天前 <strong>相关</strong>: useColorMode, useDark, useLocalStorage, useSessionStorage, useStorageAsync 创建一个可以用来访问和修改 LocalStorage 或 SessionStorage 的响应式引用（reactive ref）。</p></blockquote><p>默认使用 localStorage，可以通过第三个参数指定其他存储源。 <strong>示例</strong><strong>源代码</strong> BananaYellowMedium name: &#39;Banana&#39;color: &#39;Yellow&#39;size: &#39;Medium&#39;count: 0 <strong>使用方法</strong><strong>提示</strong> 在使用 Nuxt 3 时，此函数不会被自动导入，因为会优先使用 Nitro 内置的 useStorage()。如果您想使用 VueUse 提供的这个函数，请显式导入。 import { useStorage } from &#39;@vueuse/core&#39; _// 绑定对象_const state = useStorage(&#39;my-store&#39;, { hello: &#39;hi&#39;, greeting: &#39;Hello&#39; }) _// 绑定布尔值_const flag = useStorage(&#39;my-flag&#39;, true) <em>// 返回 Ref&lt;boolean&gt;</em> _// 绑定数字_const count = useStorage(&#39;my-count&#39;, 0) <em>// 返回 Ref&lt;number&gt;</em> _// 使用 SessionStorage 绑定字符串_const id = useStorage(&#39;my-id&#39;, &#39;some-string-id&#39;, sessionStorage) <em>// 返回 Ref&lt;string&gt;</em> _// 从存储中删除数据_state.value = null</p><p><strong>合并默认值</strong> 默认情况下，useStorage 会优先使用存储中的值，而忽略提供的默认值。请注意，当您在默认值中添加更多属性时，如果客户端的存储中没有该键，则该键可能是 undefined。 localStorage.setItem(&#39;my-store&#39;, &#39;{&quot;hello&quot;: &quot;hello&quot;}&#39;) const state = useStorage(&#39;my-store&#39;, { hello: &#39;hi&#39;, greeting: &#39;hello&#39; }, localStorage) console.log(state.value.greeting) <em>// undefined，因为存储中没有该值</em></p><p>要解决这个问题，可以启用 mergeDefaults 选项。 <strong>TypeScript 示例</strong> localStorage.setItem(&#39;my-store&#39;, &#39;{&quot;hello&quot;: &quot;nihao&quot;}&#39;) const state = useStorage( &#39;my-store&#39;, { hello: &#39;hi&#39;, greeting: &#39;hello&#39; }, localStorage, { mergeDefaults: true } <em>// &lt;--</em>) console.log(state.value.hello) _// &#39;nihao&#39;，来自存储_console.log(state.value.greeting) <em>// &#39;hello&#39;，来自合并的默认值</em></p><p>当将其设置为 true 时，它会对对象执行浅合并（shallow merge）。您还可以传递一个函数来自定义合并逻辑（例如深度合并）： <strong>TypeScript 示例</strong> const state = useStorage( &#39;my-store&#39;, { hello: &#39;hi&#39;, greeting: &#39;hello&#39; }, localStorage, { mergeDefaults: (storageValue, defaults) =&gt; deepMerge(defaults, storageValue) } <em>// &lt;--</em>)</p><p><strong>自定义序列化</strong> 默认情况下，useStorage 会根据提供的默认值的数据类型智能选择对应的序列化器。例如，对象使用 JSON.stringify / JSON.parse，数字使用 Number.toString / parseFloat 等。 您也可以为 useStorage 提供自定义序列化函数： <strong>TypeScript 示例</strong> import { useStorage } from &#39;@vueuse/core&#39; useStorage( &#39;key&#39;, {}, undefined, { serializer: { read: (v: any) =&gt; v ? JSON.parse(v) : null, write: (v: any) =&gt; JSON.stringify(v), }, },)</p><p>请注意，如果您将默认值设置为 null，useStorage 无法从中推断数据类型。在这种情况下，您可以提供自定义序列化器，或者显式重用内置的序列化器： import { StorageSerializers, useStorage } from &#39;@vueuse/core&#39; const objectLike = useStorage(&#39;key&#39;, null, undefined, { serializer: StorageSerializers.object })objectLike.value = { foo: &#39;bar&#39; }</p><p><strong>类型声明</strong> （此处原文未提供具体的类型声明内容，通常会包含 useStorage 的 TypeScript 类型定义，例如参数和返回值的类型。以下是一个可能的示例：） function useStorage&lt;T&gt;( key: string, defaultValue: T, storage?: Storage, options?: { mergeDefaults?: boolean | ((storageValue: T, defaults: T) =&gt; T); serializer?: { read: (v: string) =&gt; T; write: (v: T) =&gt; string; }; }): Ref&lt;T&gt;</p><p><strong>翻译说明</strong></p><ol><li><strong>技术术语保留原文</strong>：如 LocalStorage、SessionStorage、Ref 等，保持英文以符合开发者的习惯。</li><li><strong>代码示例翻译</strong>：代码部分保留原文，仅翻译注释和说明文字。</li><li><strong>逻辑清晰</strong>：按照原文结构逐段翻译，确保内容连贯。</li><li><strong>缺失部分补充</strong>：原文中提到的“Type Declarations”未提供具体内容，我根据上下文推测补充了一个可能的类型声明示例。</li></ol><p>如果您需要进一步调整或补充，请告诉我！</p><p>useStorage 是由 VueUse 提供的一个工具函数（composition function），它的主要作用是<strong>在 Vue 应用中创建一个与浏览器存储（如 localStorage 或 sessionStorage）绑定的响应式引用（reactive ref）</strong>。通过这个函数，你可以方便地将数据存储到浏览器的本地存储中，并在数据发生变化时自动同步，同时保持 Vue 的响应式特性。 以下是它的作用和使用方法的详细说明：</p><p><strong>作用</strong></p><ol><li><strong>数据持久化</strong>****useStorage 允许你将 Vue 的响应式数据与浏览器的 localStorage 或 sessionStorage 绑定，实现数据的持久化存储。即便用户刷新页面或关闭浏览器（对于 localStorage），数据也不会丢失。</li><li><strong>响应式同步</strong>****当你修改 useStorage 返回的 ref 值时，它会自动更新存储中的数据；反过来，如果存储中的数据被外部修改（例如通过开发者工具或另一个标签页），ref 的值也会同步更新（在某些条件下需要监听存储事件）。</li><li><strong>类型支持</strong>****支持多种数据类型（如对象、布尔值、数字、字符串等），并通过内置或自定义序列化器自动处理数据的读写。</li><li><strong>灵活性</strong>****你可以选择使用 localStorage（默认）或 sessionStorage，还可以自定义序列化逻辑或默认值合并策略。</li></ol><p><strong>应该怎么用</strong> useStorage 的使用场景非常广泛，尤其适合需要持久化存储状态的场景，例如用户设置、表单数据、计数器等。以下是具体的使用方法和步骤： <strong>基本用法</strong></p><ol><li><strong>安装 VueUse</strong>****确保你的项目中已安装 @vueuse/core：bashCollapseWrapCopynpm install @vueuse/core</li><li><strong>导入并使用</strong>****在你的 Vue 组件中导入 useStorage，然后创建一个绑定到存储的响应式变量：javascriptCollapseWrapCopyimport { useStorage } from &#39;@vueuse/core&#39;export default { setup() { <em>// 创建一个绑定到 localStorage 的响应式对象</em> const state = useStorage(&#39;my-store&#39;, { name: &#39;John&#39;, age: 25 }) <em>// 创建一个绑定到 sessionStorage 的响应式字符串</em> const id = useStorage(&#39;my-id&#39;, &#39;user-123&#39;, sessionStorage) return { state, id } }}</li><li><strong>在模板中使用</strong>****因为 state 和 id 是响应式的，你可以直接在模板中使用它们：htmlCollapseWrapCopy&lt;template&gt; &lt;div&gt; &lt;p&gt;Name: {{ state.name }}&lt;/p&gt; &lt;p&gt;ID: {{ id }}&lt;/p&gt; &lt;button @click=&quot;state.name = &#39;Jane&#39;&quot;&gt;Change Name&lt;/button&gt; &lt;/div&gt;&lt;/template&gt;当你点击按钮修改 state.name 时，localStorage 中的值会自动更新为 {&quot;name&quot;: &quot;Jane&quot;, &quot;age&quot;: 25}。</li></ol><p><strong>高级用法</strong></p><ol><li><strong>绑定不同类型的数据</strong>****useStorage 支持多种数据类型，默认会根据类型选择合适的序列化方式： javascriptCollapseWrapCopyconst flag = useStorage(&#39;my-flag&#39;, true) _// 布尔值_const count = useStorage(&#39;my-count&#39;, 0) _// 数字_const text = useStorage(&#39;my-text&#39;, &#39;hello&#39;) <em>// 字符串</em></li><li><strong>删除存储数据</strong>****将值设置为 null 会删除对应的存储项： javascriptCollapseWrapCopystate.value = null <em>// 删除 &#39;my-store&#39; 键对应的数据</em></li><li><strong>合并默认值</strong>****如果存储中的数据不完整，可以使用 mergeDefaults 选项补全默认值： javascriptCollapseWrapCopylocalStorage.setItem(&#39;my-store&#39;, &#39;{&quot;name&quot;: &quot;Alice&quot;}&#39;)const state = useStorage( &#39;my-store&#39;, { name: &#39;Bob&#39;, age: 30 }, localStorage, { mergeDefaults: true })console.log(state.value) <em>// { name: &#39;Alice&#39;, age: 30 }</em></li><li><strong>自定义序列化</strong>****如果默认的序列化方式不满足需求，可以自定义： javascriptCollapseWrapCopyconst customState = useStorage( &#39;custom-key&#39;, { data: &#39;test&#39; }, localStorage, { serializer: { read: (v) =&gt; v ? JSON.parse(v) : null, write: (v) =&gt; JSON.stringify(v), }, })</li><li><strong>Nuxt 3 注意事项</strong>****如果使用 Nuxt 3，默认会优先使用 Nitro 的 useStorage，需要显式导入 VueUse 的版本： javascriptCollapseWrapCopyimport { useStorage } from &#39;@vueuse/core&#39;</li></ol><p><strong>使用场景</strong></p><ol><li><strong>保存用户偏好设置</strong>****例如主题模式（暗黑/明亮）、语言选择等： javascriptCollapseWrapCopyconst theme = useStorage(&#39;theme&#39;, &#39;light&#39;)</li><li><strong>表单数据暂存</strong>****用户填写表单时，实时保存到 localStorage，防止刷新丢失： javascriptCollapseWrapCopyconst form = useStorage(&#39;form-data&#39;, { username: &#39;&#39;, email: &#39;&#39; })</li><li><strong>计数器或状态管理</strong>****记录页面访问次数或某些操作的状态： javascriptCollapseWrapCopyconst visitCount = useStorage(&#39;visit-count&#39;, 0)visitCount.value++</li></ol><p><strong>注意事项</strong></p><ol><li><strong>存储限制</strong>****localStorage 和 sessionStorage 都有大小限制（通常为 5-10MB），不适合存储大数据。</li><li><strong>跨标签页同步</strong>****useStorage 的响应式更新仅在当前页面有效。如果需要在多个标签页间同步，可以结合 storage 事件监听。</li><li><strong>序列化问题</strong>****如果存储的值不是有效的 JSON 格式（例如手动修改了存储），可能导致解析错误。使用自定义序列化器可以缓解这个问题。</li></ol><p><strong>总结</strong> useStorage 是一个简单而强大的工具，帮助你在 Vue 项目中实现数据持久化和响应式管理。使用时，只需明确存储的键名、默认值和存储类型（localStorage 或 sessionStorage），即可快速上手。根据需求，还可以通过选项自定义其行为。</p></div>',1)])])}const m=t(a,[["render",g]]);export{c as __pageData,m as default};
